// Ghost Visuals Module

const GHOST_COLORS = {
    chase: '#FF0000',    // Red
    ambush: '#FFB8FF',  // Pink
    patrol: '#00FFFF',  // Cyan
    random: '#FFA500',  // Orange
    frightened: '#0000FF' // Blue when power-up active
};

function drawGhost(ctx, x, y, state, identity) {
    const color = state === 'frightened' ? GHOST_COLORS.frightened : GHOST_COLORS[identity];
    ctx.fillStyle = color;
    ctx.beginPath();
    // Draw ghost body as a circle with a wavy bottom
    ctx.arc(x, y - 10, 12, Math.PI, 0, false); // head
    ctx.lineTo(x + 12, y + 10); // right bottom
    for (let i = 0; i < 4; i++) {
        const waveX = x + 12 - i * 6;
        const waveY = y + 10 + (i % 2 === 0 ? 5 : -5);
        ctx.lineTo(waveX, waveY);
    }
    ctx.lineTo(x - 12, y + 10); // left bottom
    ctx.closePath();
    ctx.fill();

    // Draw eyes
    ctx.fillStyle = 'white';
    ctx.beginPath();
    ctx.ellipse(x - 5, y - 5, 4, 6, 0, 0, 2 * Math.PI);
    ctx.ellipse(x + 5, y - 5, 4, 6, 0, 0, 2 * Math.PI);
    ctx.fill();

    ctx.fillStyle = 'black';
    ctx.beginPath();
    ctx.ellipse(x - 5, y - 5, 2, 4, 0, 0, 2 * Math.PI);
    ctx.ellipse(x + 5, y - 5, 2, 4, 0, 0, 2 * Math.PI);
    ctx.fill();
}

