class GhostIdentity(Enum):
    BLINKY = 'Blinky'
    PINKY = 'Pinky'
    INKY = 'Inky'
    CLYDE = 'Clyde'

class GhostState(Enum):
    CHASE = 'chase'
    FLEE = 'flee'
    EATEN = 'eaten'
    PATROL = 'patrol'
    AMBUSH = 'ambush'

class GhostManager:
    def __init__(self, start_positions=None):
        # start_positions can be used for future expansion, currently unused
        self.states = {
            GhostIdentity.BLINKY: GhostState.CHASE,
            GhostIdentity.PINKY: GhostState.CHASE,
            GhostIdentity.INKY: GhostState.CHASE,
            GhostIdentity.CLYDE: GhostState.CHASE
        }

    def get_ghost_state(self, identity: GhostIdentity) -> GhostState:
        return self.states.get(identity, GhostState.CHASE)

    def set_ghost_state(self, identity: GhostIdentity, state: GhostState):
        if identity in self.states:
            self.states[identity] = state

    def get_all_states(self):
        # Return dict of ghost name string to state string
        return {identity.value: self.states[identity].value for identity in self.states}

