const ghostColors = [
  '#FF0000', // Red
  '#00FF00', // Green
  '#0000FF', // Blue
  '#FFFF00', // Yellow
  '#FF00FF', // Magenta
  '#00FFFF'  // Cyan
];

const ghostStates = {
  NORMAL: 'normal',
  FRIGHTENED: 'frightened',
  EATEN: 'eaten'
};

// Draw a ghost at interpolated position with color and state visuals
export function drawGhost(ctx, ghost, interpolation) {
  // Interpolate position
  const x = lerp(ghost.prevPos.x, ghost.pos.x, interpolation);
  const y = lerp(ghost.prevPos.y, ghost.pos.y, interpolation);

  // Determine color based on ghost id
  const color = ghostColors[ghost.id % ghostColors.length] || '#FFFFFF';

  // Determine visual style based on state
  let fillColor = color;
  if (ghost.state === ghostStates.FRIGHTENED) {
    fillColor = 'blue';
  } else if (ghost.state === ghostStates.EATEN) {
    fillColor = 'white';
  }

  // Draw ghost body
  ctx.fillStyle = fillColor;
  ctx.beginPath();
  ctx.arc(x * 30 + 15, y * 30 + 15, 12, Math.PI, 0, false); // head semicircle
  ctx.lineTo(x * 30 + 27, y * 30 + 30); // right bottom
  ctx.lineTo(x * 30 + 3, y * 30 + 30); // left bottom
  ctx.closePath();
  ctx.fill();

  // Draw eyes
  ctx.fillStyle = 'white';
  ctx.beginPath();
  ctx.arc(x * 30 + 8, y * 30 + 12, 3, 0, 2 * Math.PI);
  ctx.arc(x * 30 + 22, y * 30 + 12, 3, 0, 2 * Math.PI);
  ctx.fill();

  ctx.fillStyle = 'black';n  ctx.beginPath();
  ctx.arc(x * 30 + 8 + ghost.eyeOffsetX, y * 30 + 12 + ghost.eyeOffsetY, 1.5, 0, 2 * Math.PI);
  ctx.arc(x * 30 + 22 + ghost.eyeOffsetX, y * 30 + 12 + ghost.eyeOffsetY, 1.5, 0, 2 * Math.PI);
  ctx.fill();
}

// Linear interpolation helper
function lerp(a, b, t) {
  return a + (b - a) * t;
}

// Export ghost states for use elsewhere
export { ghostStates };

